#!/usr/bin/env python3
"""High school Personal Financial Literacy and Economics (TEKS 113.76.d). Original questions."""
import sys, os
sys.path.insert(0, os.path.dirname(__file__))
from common import *

B = Bank('113.76.d.', 999, own='hs_pfle.jsonl')
def H(code, d, q, right, wrong, e): return B.hand(code, d, q, right, wrong, e)

# 1 economic basics
H('1.A', 3, "A student chooses to work a shift instead of going to a ballgame. What is the opportunity cost of working?", "the enjoyment of the ballgame", ["the wages earned", "the cost of gas", "nothing at all"], "Opportunity cost is the next best alternative given up.")
H('1.A', 3, "Scarcity exists because what?", "people's wants are unlimited but resources are limited", ["there is too much of everything", "prices never change", "money is free"], "Scarcity forces choices.")
H('1.B', 3, "On a production-possibilities curve, a point inside the curve shows what?", "resources are not fully or efficiently used", ["the economy is at maximum output", "output is impossible", "prices are rising"], "Points on the curve are efficient; inside is underuse.")
H('1.B', 3, "A point outside a production-possibilities curve is what?", "unattainable with current resources and technology", ["efficient", "wasteful", "already achieved"], "Growth could make it attainable later.")
H('1.C', 3, "Moving along a production-possibilities curve to make more of one good shows what?", "a trade-off, because less of another good is made", ["no cost", "unlimited resources", "a price decrease"], "Each choice has a cost.")
H('1.D', 3, "In the circular flow model, households provide firms with what?", "resources such as labor", ["finished goods", "tax revenue", "patents"], "Households sell resources to firms in exchange for income.")
H('1.D', 3, "In the circular flow model, firms pay households for resources with what?", "wages, rent and interest", ["products", "taxes", "tariffs"], "Payments become household income.")
H('1.E', 3, "According to the law of demand, when the price of a good rises, what usually happens?", "the quantity demanded falls", ["the quantity demanded rises", "supply disappears", "demand becomes zero"], "Higher prices reduce purchases.")
H('1.E', 3, "According to the law of supply, when the price of a good rises, producers usually do what?", "supply more", ["supply less", "stop selling", "lower costs"], "Higher prices raise profit incentive.")
H('1.F', 3, "On a supply-and-demand graph, the equilibrium point is where what?", "supply and demand curves intersect", ["demand is zero", "supply is zero", "the axes meet"], "At equilibrium the market clears.")
H('1.F', 3, "If the price is above equilibrium, what results?", "a surplus", ["a shortage", "balance", "inflation only"], "Quantity supplied exceeds quantity demanded.")
H('1.F', 3, "If the price is below equilibrium, what results?", "a shortage", ["a surplus", "balance", "deflation only"], "Quantity demanded exceeds quantity supplied.")
H('1.G', 3, "A change in consumer income or tastes is an example of what?", "a non-price determinant of demand", ["a determinant of supply", "a price ceiling", "a tariff"], "These shift the demand curve.")
H('1.G', 3, "A new technology that lowers production costs will most likely do what to supply?", "increase it", ["decrease it", "have no effect", "make it vertical"], "Lower costs shift the supply curve right.")
H('1.H', 3, "In a resource market, who is the seller?", "households", ["firms", "the government", "banks"], "Households sell labor and land to firms.")
H('1.H', 3, "In a product market, who is the buyer?", "households", ["firms", "banks only", "the Federal Reserve"], "Households buy goods and services.")

# 2 taxes and the economy
H('2.A', 3, "A progressive tax is one in which what happens?", "higher incomes pay a higher percentage", ["everyone pays the same percentage", "lower incomes pay a higher percentage", "no one pays"], "The federal income tax is progressive.")
H('2.A', 3, "A regressive tax takes a larger share from whom?", "lower-income people", ["higher-income people", "corporations only", "no one"], "Sales taxes can be regressive.")
H('2.B', 3, "Social Security taxes (FICA) pay for what?", "retirement, survivor and disability benefits", ["highways", "defense only", "public schools"], "Workers and employers both contribute.")
H('2.B', 3, "Which tax is paid mostly by local governments from property owners?", "property tax", ["income tax", "tariff", "payroll tax"], "Local schools rely on it.")
H('2.C', 3, "All real-world economies are what?", "mixed, with both market and government roles", ["pure market only", "pure command only", "traditional only"], "They lie on a spectrum.")
H('2.D', 3, "Which is a benefit of the U.S. free enterprise system?", "private property and the profit motive", ["government ownership of all firms", "price controls on everything", "no competition"], "Incentives encourage innovation.")
H('2.D', 3, "Competition in free enterprise helps consumers because it does what?", "pushes firms toward lower prices and better products", ["raises all prices", "ends choice", "eliminates quality"], "Firms compete for customers.")
H('2.E', 3, "A goal of full employment means what?", "most people who want jobs can find them", ["no one works", "wages are zero", "prices rise quickly"], "Some frictional unemployment remains.")
H('2.E', 3, "Price stability means what?", "keeping inflation low and predictable", ["prices never change", "prices always rise", "prices fall rapidly"], "Stable prices help planning.")
H('2.F', 3, "Lowering taxes and raising government spending to boost a weak economy is what kind of policy?", "expansionary fiscal policy", ["contractionary fiscal policy", "monetary policy", "tariff policy"], "It aims to raise demand.")
H('2.G', 3, "When the Federal Reserve raises interest rates, borrowing becomes what?", "more expensive", ["cheaper", "free", "illegal"], "Higher rates slow spending and inflation.")
H('2.G', 3, "The Federal Reserve is the nation's what?", "central bank", ["tax collector", "stock exchange", "insurance company"], "It manages money supply and interest rates.")

# 3 education and careers
H('3.A', 3, "On average, how does education level relate to earnings?", "more education usually means higher lifetime earnings", ["more education always means lower pay", "education has no relation", "only experience matters"], "Earnings rise with education on average.")
H('3.A', 3, "Unemployment rates are generally what for workers with more education?", "lower", ["higher", "the same", "not tracked"], "Education improves job security.")
H('3.B', 3, "Which cost should be compared when choosing a postsecondary option?", "tuition, fees, living costs and expected earnings", ["only the mascot", "only the weather", "only the distance"], "Weigh costs and benefits.")
