H('3.D', 3, "A grant is financial aid that does what?", "does not need to be repaid", ["must be repaid at once", "is a type of credit card", "is a loan with high interest"], "Pell Grants are need-based.")
H('3.E', 3, "A Student Aid Report (SAR) summarizes what?", "the information from a FAFSA and the expected family contribution", ["a student's grades", "a bank balance", "a credit score"], "It helps colleges determine aid.")
H('3.F', 3, "To align careers with interests, a student should do what?", "research jobs, required training and earnings", ["pick randomly", "ignore skills", "avoid planning"], "Match interests to opportunities.")

# 4 income
H('4.A', 3, "Interest earned on a savings account is a source of what?", "income", ["debt", "a tax deduction only", "insurance"], "Income also includes wages, profits and rent.")
H('4.A', 3, "Money earned by a worker for hours worked is called what?", "wages", ["dividends", "rent", "profit"], "Wages are payment for labor.")
