H('4.D', 3, "Which factor is likely to raise pay in a career?", "high demand for the skill", ["a lack of training", "many available workers", "low qualifications"], "Scarce skills pay more.")

# 5 entrepreneurship
H('5.A', 3, "An entrepreneur is a person who does what?", "starts and manages a business taking financial risk", ["works only for wages", "owns only stocks", "inherits a business"], "Entrepreneurs create new ventures.")
H('5.B', 3, "An entrepreneur earns profit when what?", "revenue is greater than costs", ["costs are greater than revenue", "taxes are zero", "sales are zero"], "Profit = revenue - cost.")
